const f="/host/workspace-ro/alpha-strategy-review-state.json";
if(!fs.existsSync(f)){process.stdout.write(JSON.stringify({readable:false})+"\n");process.exit(0);}
const buf=fs.readFileSync(f);
const d=JSON.parse(buf.toString("utf8"));
const cs=d.current_snapshot||{};
const n=(v)=>Array.isArray(v)?v.length:null;
process.stdout.write(JSON.stringify({readable:true,path:f,bytes:buf.length,sha256:crypto.createHash("sha256").update(buf).digest("hex"),last_reviewed_at:d.last_reviewed_at||null,last_reviewed_commit:d.last_reviewed_commit||null,deferred_remote_head:d.deferred_remote_head||null,counts:{pass:n(cs.pass),pass_with_caveat:n(cs.pass_with_caveat),remediate:n(cs.remediate),reject:n(cs.reject),pending_ingestion:n(d.pending_ingestion),deferred_delta:n(d.deferred_delta),ingested_wiki_records:n(d.ingested_wiki_records)}})+"\n");
