// SHADOW MODE assembler — deterministic, read-only.
// Inputs: stdout JSON from read-only Execute Command source nodes (cat/ls/wc/sha256sum/node-read projections only).
// Output: one machine-readable shadow snapshot item (+ binary copy for the single output node).
// This node performs no writes, no network access and no control-plane mutation.

const VOCAB = {
  WAITING_DATA: 'candidate prerequisite/data missing but potentially recoverable',
  READY_TO_RESUME: 'previously waiting candidate whose prerequisite is now satisfied (policy: never interrupt the running family; takes priority over untouched queue candidates afterwards)',
  BLOCKED: 'genuine abnormal condition requiring intervention; not a synonym for missing data',
  TECHNICAL_INCOMPLETE: 'terminal: an objective prerequisite cannot be satisfied; no automatic resume',
  REJECT: 'terminal scientific/strategy rejection',
  PASS: 'promoted survivor (leaderboard entry)',
  RUNNING_QLIB: 'existing runtime stage: full backtest running',
  ARTIFACT_READY: 'existing runtime stage: artifacts complete, terminal not yet published',
  FAILED_SCRIPT: 'existing runtime stage: run stopped without a published terminal',
};
const TOKEN_ORDER = ['TECHNICAL_INCOMPLETE', 'READY_TO_RESUME', 'WAITING_DATA', 'RUNNING_QLIB', 'ARTIFACT_READY', 'FAILED_SCRIPT', 'BLOCKED', 'REJECT', 'PASS'];

const NODE = {
  pool: 'Pool — alpha-strategy-research pool (read-only)',
  intake: 'Intake Review — canonical intake state (read-only)',
  gate: 'Preflight Gate — prerequisite evidence (read-only)',
  dashboard: 'Candidate→Qlib→Leaderboard — dashboard projection (read-only)',
  parking: 'Parking — private survivor repo metadata (read-only)',
};

const gaps = [];
const addGap = (field, reason) => { if (!gaps.some((g) => g.field === field)) gaps.push({ field, reason }); };
const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : null);
const str = (v) => (typeof v === 'string' && v.length ? v : null);
const bool = (v) => (typeof v === 'boolean' ? v : null);
const len = (v) => (Array.isArray(v) ? v.length : null);
const get = (o, path) => path.split('.').reduce((a, k) => (a && typeof a === 'object' ? a[k] : undefined), o);

function stdoutOf(name) {
  try {
    const item = $(name).first();
    const s = item && item.json ? item.json.stdout : null;
    return typeof s === 'string' && s.trim().length ? s : null;
  } catch (e) {
    return null;
  }
}
function parseSource(name, label) {
  const text = stdoutOf(name);
  if (text === null) { addGap(label, 'source node returned no stdout (unreadable or empty)'); return null; }
  try { return JSON.parse(text); } catch (e) { addGap(label, 'stdout is not a valid JSON object'); return null; }
}
function splitMeta(text, prefix, label) {
  if (text === null) { addGap(label, 'source node produced no stdout (unreadable or empty)'); return { meta: null, body: null }; }
  const nl = text.indexOf('\n');
  const first = nl === -1 ? text : text.slice(0, nl);
  const rest = nl === -1 ? '' : text.slice(nl + 1);
  if (!first.startsWith(prefix)) { addGap(label, 'stdout did not start with the expected metadata line'); return { meta: null, body: text }; }
  let meta = null;
  try { meta = JSON.parse(first.slice(prefix.length)); } catch (e) { addGap(label, 'metadata line is not valid JSON'); }
  return { meta, body: rest };
}

const pool = parseSource(NODE.pool, 'strategy pool inventory');
const intake = parseSource(NODE.intake, 'canonical intake state');
const gateRec = parseSource(NODE.gate, 'prerequisite gate evidence');
const parking = parseSource(NODE.parking, 'survivor parking metadata');
const dashRaw = splitMeta(stdoutOf(NODE.dashboard), 'dashboard_meta: ', 'dashboard projection');
let dashboard = null;
if (typeof dashRaw.body === 'string' && dashRaw.body.trim().length) {
  try { dashboard = JSON.parse(dashRaw.body); } catch (e) { addGap('dashboard projection', 'payload is not valid JSON'); }
} else { addGap('dashboard projection', 'no JSON payload available'); }

const snap = get(intake, 'counts') || null;
const lb = get(dashboard, 'leaderboard') || null;
const health = get(dashboard, 'health') || null;
const cur = get(dashboard, 'current') || null;
const funnel = get(dashboard, 'funnel') || null;
const parkMeta = get(parking, 'meta') || null;

const counts = {
  pool_root_md_total: num(get(pool, 'root_md_total')),
  pool_records_total: num(get(pool, 'records')),
  intake_pass: num(get(snap, 'pass')),
  intake_pass_with_caveat: num(get(snap, 'pass_with_caveat')),
  intake_remediate: num(get(snap, 'remediate')),
  intake_reject: num(get(snap, 'reject')),
  intake_pending_ingestion: num(get(snap, 'pending_ingestion')),
  intake_deferred_delta: num(get(snap, 'deferred_delta')),
  intake_ingested_wiki_records: num(get(snap, 'ingested_wiki_records')),
  wiki_reviewed: num(get(funnel, 'wiki_brain.reviewed')),
  wiki_ingested: num(get(funnel, 'wiki_brain.ingested')),
  families_registered: num(get(funnel, 'backtested.registered')),
  families_backtested: num(get(funnel, 'backtested.families')),
  workload_evaluations: num(get(funnel, 'workload.evaluations')),
  leaderboard_count: num(get(lb, 'count')),
  leaderboard_shown: num(get(lb, 'shown')),
  current_family_id: str(get(cur, 'family_id')),
  current_stage: str(get(cur, 'stage')),
  current_progress_pct: num(get(cur, 'progress_pct')),
  current_card_status: str(get(cur, 'card_status')),
  current_kanban_task_id: str(get(cur, 'kanban_task_id')),
  runtime_health_status: str(get(health, 'status')),
  runtime_health_active_count: num(get(health, 'active_count')),
  gate_record_count: num(get(gateRec, 'record_count')),
  gate_record_matched_current_family: bool(get(gateRec, 'matched')),
  parking_survivor_dirs: num(get(parking, 'survivor_dirs')),
  parking_survivor_count: num(get(parkMeta, 'survivor_count')),
  parking_top10_count: num(get(parkMeta, 'top10_count')),
};

let gateView = null;
const gateRecord = get(gateRec, 'record');
if (gateRecord && typeof gateRecord === 'object') {
  const texts = [str(gateRecord.conclusion), str(gateRecord.verdict)].filter((t) => t !== null);
  let token = null;
  let tokenText = null;
  for (const t of texts) {
    const hit = TOKEN_ORDER.find((k) => t.indexOf(k) !== -1);
    if (hit) { token = hit; tokenText = t; break; }
  }
  gateView = {
    record_path: str(get(gateRec, 'path')),
    record_sha256: str(get(gateRec, 'sha256')),
    document_kind: str(gateRecord.document_kind),
    family_id: str(gateRecord.family_id),
    round_id: str(gateRecord.round_id),
    kanban_task_id: str(gateRecord.kanban_task_id),
    recorded_at_utc: str(gateRecord.created_at_utc),
    conclusion: str(gateRecord.conclusion),
    verdict_field: str(gateRecord.verdict),
    performance_claimable: bool(gateRecord.performance_claimable),
    required_data_available: bool(gateRecord.required_data_available),
    attempts_launched: num(gateRecord.attempts_launched),
    terminal_sentinels: num(gateRecord.terminal_sentinels),
    decisive_absences: num(gateRecord.decisive_absences),
    matched_current_family: bool(get(gateRec, 'matched')),
    shadow_state: token,
    shadow_state_source: token ? 'verbatim token "' + token + '" inside: ' + tokenText : null,
  };
  if (token === null) addGap('gate.shadow_state', 'matched gate record carries no recognised vocabulary token');
} else {
  addGap('gate.record', 'no prerequisite-gate evidence record matched the current family');
}

const asOf = (v) => str(v);
const stages = [];
const push = (o) => stages.push(Object.assign({ order: stages.length + 1 }, o));
const RT_TOKENS = ['RUNNING_QLIB', 'ARTIFACT_READY', 'FAILED_SCRIPT'];
const qlibState = counts.current_stage && RT_TOKENS.indexOf(counts.current_stage) !== -1 ? counts.current_stage : null;
const incidents = Array.isArray(get(health, 'active')) ? get(health, 'active').map((i) => ({ kind: str(i.kind), label: str(i.label), first_seen_utc: str(i.first_seen_utc) })) : [];
const topEntries = Array.isArray(get(lb, 'entries')) ? get(lb, 'entries').map((e) => ({ rank: e.rank, cohort: str(e.cohort), sharpe: num(e.sharpe), annualized_return: num(e.annualized_return), max_dd_pct: num(e.max_dd_pct), evidence_state: str(e.evidence_state) })) : null;

push({ stage: 'strategy_research', label: 'Strategy Research (upstream)', shadow_state: null, state_provenance: null,
  observation: { note: 'Operator/ChatGPT-directed research produces pool records upstream; it has no machine-readable shadow source in shadow-1.' } });
push({ stage: 'github_strategy_pool', label: 'GitHub alpha-strategy-research pool', shadow_state: null, state_provenance: null,
  observation: { records_total: counts.pool_records_total, root_md_total: counts.pool_root_md_total, canonical_record_rule: 'root-level *.md excluding README* (alpha-strategy-research review_state.py:111)', checkout_head_sha: str(get(pool, 'checkout_head_sha')), source: 'read-only checkout of the canonical pool repo' } });
push({ stage: 'intake_review', label: 'Intake Review (canonical intake state)', shadow_state: null, state_provenance: null,
  observation: { pass: counts.intake_pass, pass_with_caveat: counts.intake_pass_with_caveat, remediate: counts.intake_remediate, reject: counts.intake_reject, pending_ingestion: counts.intake_pending_ingestion, deferred_delta: counts.intake_deferred_delta, last_reviewed_at: str(get(intake, 'last_reviewed_at')), last_reviewed_commit: str(get(intake, 'last_reviewed_commit')), branch_semantics: { accepted: 'PASS + PASS-WITH-CAVEAT that actually ingested -> Wiki Brain (+ sibling candidate append)', rejected: 'terminal normal screening outcome', remediate: 'not accepted yet; not a system error', error: 'only actual system/read/parsing failure; never conflated with reject/remediate' } } });
push({ stage: 'wiki_brain', label: 'Wiki Brain (canonical ingestions)', shadow_state: null, state_provenance: null,
  observation: { reviewed: counts.wiki_reviewed, ingested: counts.wiki_ingested, ingested_wiki_records: counts.intake_ingested_wiki_records } });
push({ stage: 'candidate_queue', label: 'Candidate Queue (registered families)', shadow_state: null, state_provenance: null,
  observation: { registered_families: counts.families_registered, current_family_id: counts.current_family_id, current_kanban_task_id: counts.current_kanban_task_id, current_card_status: counts.current_card_status } });
push({ stage: 'data_preflight_gate', label: 'Data / Preflight Gate (prerequisite evidence)', shadow_state: gateView ? gateView.shadow_state : null,
  state_provenance: gateView ? gateView.shadow_state_source : null, observation: gateView || { note: 'no prerequisite-gate record matched the current family' } });
push({ stage: 'qlib_full_backtest', label: 'Qlib Full Backtest (runtime stage)', shadow_state: qlibState, state_provenance: qlibState ? 'verbatim runtime stage from the dashboard projection' : null,
  observation: { stage: counts.current_stage, progress_pct: counts.current_progress_pct, progress_text: str(get(cur, 'progress_text')), note: str(get(cur, 'note')), cumulative_evaluations: counts.workload_evaluations, backtested_families: counts.families_backtested } });
push({ stage: 'result_verdict', label: 'Result / Verdict', shadow_state: null, state_provenance: null,
  observation: { last_activity_utc: str(get(cur, 'last_activity_utc')), runtime_health_status: counts.runtime_health_status, runtime_health_active_count: counts.runtime_health_active_count, watchdog_summary: str(get(health, 'summary')), active_incidents: incidents } });
push({ stage: 'survivor', label: 'Survivor (promoted)', shadow_state: counts.leaderboard_count ? 'PASS' : null,
  state_provenance: counts.leaderboard_count ? 'shadow mapping: a leaderboard entry is the survivor promotion trigger (contract 28.1); value taken from the dashboard projection leaderboard count' : null,
  observation: { leaderboard_count: counts.leaderboard_count } });
push({ stage: 'leaderboard', label: 'Leaderboard (canonical projection)', shadow_state: null, state_provenance: null,
  observation: { count: counts.leaderboard_count, shown: counts.leaderboard_shown, as_of_utc: str(get(lb, 'as_of_utc')), top: topEntries } });
push({ stage: 'private_repo_parking', label: 'Private Repo Parking (validated-survivor-research)', shadow_state: null, state_provenance: null,
  observation: { repo_present: bool(get(parking, 'repo_present')), parked_survivor_dirs: counts.parking_survivor_dirs, parked_survivor_count: counts.parking_survivor_count, parked_top10_count: counts.parking_top10_count, leaderboard_present: bool(get(parking, 'leaderboard_present')), leaderboard_bytes: num(get(parking, 'leaderboard_bytes')), leaderboard_generated_at_utc: asOf(get(parkMeta, 'generated_at_utc')), contract: asOf(get(parkMeta, 'contract')), mirror_head_sha: str(get(parking, 'mirror_head_sha')) } });

const bucketTotal = (counts.intake_pass !== null && counts.intake_pass_with_caveat !== null && counts.intake_remediate !== null && counts.intake_reject !== null)
  ? counts.intake_pass + counts.intake_pass_with_caveat + counts.intake_remediate + counts.intake_reject : null;
const recon = [];
const check = (name, observed, expected, ok, note) => recon.push({ check: name, observed, expected, ok, note });
check('intake buckets total vs wiki reviewed', bucketTotal, counts.wiki_reviewed, bucketTotal !== null && counts.wiki_reviewed !== null ? bucketTotal === counts.wiki_reviewed : null, 'canonical intake state vs dashboard projection');
check('ingested_wiki_records vs dashboard wiki ingested', counts.intake_ingested_wiki_records, counts.wiki_ingested, counts.intake_ingested_wiki_records !== null && counts.wiki_ingested !== null ? counts.intake_ingested_wiki_records === counts.wiki_ingested : null, 'intake state vs dashboard projection');
check('parking survivor dirs vs parking survivor_count', counts.parking_survivor_dirs, counts.parking_survivor_count, counts.parking_survivor_dirs !== null && counts.parking_survivor_count !== null ? counts.parking_survivor_dirs === counts.parking_survivor_count : null, 'filesystem mirror vs mirrored leaderboard metadata');
check('canonical leaderboard count vs parking survivor_count', counts.leaderboard_count, counts.parking_survivor_count, counts.leaderboard_count !== null && counts.parking_survivor_count !== null ? counts.leaderboard_count === counts.parking_survivor_count : null, 'shown as a gap, not resolved: the parking mirror is a separately generated subset (see its generated_at_utc and mirror_head_sha)');
check('pool records vs intake buckets + deferred_delta', counts.pool_records_total, (bucketTotal !== null && counts.intake_deferred_delta !== null) ? bucketTotal + counts.intake_deferred_delta : null, null, 'informational: the pool checkout HEAD is ahead of the last reviewed snapshot, so the difference is expected and is not an error');
check('current family gate record matched', counts.gate_record_matched_current_family, true, counts.gate_record_matched_current_family === null ? null : counts.gate_record_matched_current_family, 'prerequisite-gate evidence for the current family; no gate record is invented when absent');

const snapshot = {
  schema: 'quant-control-plane-shadow/v1',
  mode: 'SHADOW_READ_ONLY',
  generated_at_utc: new Date().toISOString(),
  control_plane: {
    mutations_enabled: false,
    mutating_nodes: [],
    only_write: '/home/node/.n8n-files/quant-control-plane-shadow.json (host: /Users/hong/workspace/n8n/files/ — the n8n deployment file area)',
    note: 'Shadow-1: every host integration is read-only; no pipeline, Kanban, candidate, leaderboard, results-root or GitHub state is written or mutated.',
  },
  sources: [
    { id: 'dashboard_projection', kind: 'existing projection', path: dashRaw.meta ? str(dashRaw.meta.path) : null, readable: dashRaw.meta ? bool(dashRaw.meta.readable) : null, bytes: dashRaw.meta ? num(dashRaw.meta.bytes) : null, sha256: dashRaw.meta ? str(dashRaw.meta.sha256) : null, as_of_utc: dashboard ? str(dashboard.generated_at_utc) : null },
    { id: 'intake_state', kind: 'canonical intake state', path: str(get(intake, 'path')), readable: bool(get(intake, 'readable')), bytes: num(get(intake, 'bytes')), sha256: str(get(intake, 'sha256')), as_of_utc: str(get(intake, 'last_reviewed_at')) },
    { id: 'pool_checkout', kind: 'canonical pool checkout (read-only)', path: '/host/workspace-ro/alpha-strategy-research', readable: pool !== null, bytes: null, sha256: null, as_of_utc: null, note: 'record count derived with the canonical rule; the checkout HEAD sha is recorded for provenance' },
    { id: 'prerequisite_gate_evidence', kind: 'repo evidence document (read-only)', path: str(get(gateRec, 'path')), readable: gateRecord !== null, bytes: num(get(gateRec, 'bytes')), sha256: str(get(gateRec, 'sha256')), as_of_utc: gateView ? gateView.recorded_at_utc : null, note: 'shadow-1 reads a fixed key set from the matched record; the record itself stays canonical in the repo' },
    { id: 'parking_repo', kind: 'private survivor mirror (read-only)', path: '/host/workspace-ro/validated-survivor-research', readable: bool(get(parking, 'repo_present')), bytes: num(get(parking, 'leaderboard_bytes')), sha256: str(get(parking, 'leaderboard_sha256')), as_of_utc: asOf(get(parkMeta, 'generated_at_utc')) },
  ],
  counts,
  topology: stages,
  reconciliation: recon,
  vocabulary: VOCAB,
  resume_policy: {
    documented: true,
    enabled: false,
    rule: VOCAB.READY_TO_RESUME,
    shadow_behaviour: 'visualise only; shadow-1 must not delay, reorder, interrupt or resume any family',
    ready_to_resume: { value: null, reason: 'not derivable in shadow-1: deciding READY_TO_RESUME requires re-running the family prerequisite check against canonical raw (/Volumes/ExpansionDrive/market-data-raw), which is deliberately not mounted or executed here' },
  },
  gaps,
};
addGap('candidate_pool_file', 'canonical candidate pool (/Volumes/ExpansionDrive/qlib-results/_handoff/candidates.json) is not read in shadow-1; the queue is shown from the dashboard projection instead');
addGap('results_root', 'canonical results root is not mounted; Qlib stage/progress and the leaderboard come from the existing projection only');
addGap('kanban_direct_read', 'only the projection card read-back field is shown; n8n does not read the Kanban DB directly');
snapshot.gaps = gaps;

const payload = JSON.stringify(snapshot, null, 2);
const binary = await this.helpers.prepareBinaryData(Buffer.from(payload, 'utf8'), 'quant-control-plane-shadow.json', 'application/json');
return [{ json: snapshot, binary: { data: binary } }];
